INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7b5fc20a-94b8-505d-b07b-c4e8cf84e4ec', 'd59b6b0c-a9c8-5ebf-abfe-16aed2a8784f', 'postal_code', 'Postal Code', 'The postal or ZIP code of the address. Entered according to the country''s format; used for delivery, tax zones and distance calculation.', 10, 30, NULL, FALSE, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
