INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b515d21f-9c1c-5650-9688-7158e1b9465f', 'Energy Asset', 'Maintain Energy Asset records', 'Create, find and maintain Energy Asset records. The list shows every Energy Asset you have access to — select a row to open it, or use New to add one. Each row is a single Energy Asset, described by 7 fields.

Id and Asset Code are unique: no two Energy Asset records may share the same value, and a save that would duplicate one is rejected. Asset Code, Asset Type, Status and Organization must be filled in before the record can be saved.

Every Energy Asset points at Location and Organization. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Energy Asset then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Energy Asset with no rules or workflows attached is marked Final immediately.', 'box', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('48e4fca1-fe45-5da5-abf9-913d467761a8', 'bus_energy_asset', 'Energy Asset', 'A physical asset used to generate, transmit, distribute, store or consume energy. Energy businesses run on physical plant. Each asset record carries its type and capacity, so planners know what is available and maintenance work can be tracked against the equipment it concerns. Registered when plant is planned or commissioned; updated through maintenance and outages; read by operations, asset management and regulators. An asset belongs to an Organization, stands at a Location and is the subject of MaintenanceWorkOrders. An asset is planned, goes active when commissioned, moves to maintenance when taken out of service for work, and is eventually decommissioned for good. A 50 MW solar array at the Almeria site, commissioned in 2024 and under annual maintenance each spring.', 'box', 'A', FALSE, FALSE, FALSE, TRUE, 'b515d21f-9c1c-5650-9688-7158e1b9465f', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b92ecdcc-53a6-5673-a772-97b0e50acb8e', 'b515d21f-9c1c-5650-9688-7158e1b9465f', '48e4fca1-fe45-5da5-abf9-913d467761a8', 'Energy Asset', 'Shows one Energy Asset at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Location and Organization are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
