INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d004248a-fcd3-510d-9ebb-ebc86db55d98', '4cedec4f-4f4f-5d0e-973e-3f376f03a341', 'meter_type', 'Meter Type', 'The utility resource that the meter measures. Chosen at registration; decides the unit of measure and the tariffs that can apply. Electrical energy consumed or produced. Natural gas consumed. Water consumed. Steam or district heat consumed. Electricity generated by solar installations. Any other metered resource.', 1004, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
