VALUES ('1183c603-ee2e-5fbf-b8d6-0810394dff9d', 'bus_person_status', 'Person Status', 'The values of person status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '643c0f28-aebc-5214-bf62-e6d24f5d1039', 'U', TRUE, 'system', 'system', NOW(), NOW())
