VALUES ('a3966509-c735-5003-aef3-24ca0541c982', 'bus_address_status', 'Address Status', 'The values of address status, maintained by the business: reword, reorder or retire a value here and every form that offers the list follows.', 'list', 'A', FALSE, FALSE, FALSE, TRUE, '5e377159-9102-5b08-9d4c-6b2a37db8329', 'U', TRUE, 'system', 'system', NOW(), NOW())
