-- --------------------------------------------------------------------------
-- Meter Reading (bus_meter_reading)
-- --------------------------------------------------------------------------
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('064e7434-ab95-5be8-97c3-d14244f22506', 'bus_meter_reading', 'Meter Reading', 'A measured value recorded from a utility meter at a point in time. Bills and consumption figures are computed from readings. Each reading records the value, when it was taken, how it was obtained and whether it can be trusted. Entered by meter readers, imported from smart meters, or estimated; read by billing and analysis. A reading belongs to one EnergyMeter and uses a UnitOfMeasure. The electricity meter at a customer''s premises reads 48,213.4 kWh on 1 April at 08:00.', 'gauge', 'A', FALSE, FALSE, FALSE, TRUE, '4291bda6-9d4e-568c-af82-db9f600412f4', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2436fc1-adc0-5452-a774-dca68f3879b7', '4291bda6-9d4e-568c-af82-db9f600412f4', '064e7434-ab95-5be8-97c3-d14244f22506', 'Meter Reading', 'Shows one Meter Reading at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Unit Of Measure is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 1, 20, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
